#!/usr/bin/env python3
"""Write src/fold_table.rs: the Unicode data behind lazaret_archive::path_key.

    python3 rust/crates/lazaret-archive/tests/fixtures/generate_fold_table.py           # rewrite
    python3 rust/crates/lazaret-archive/tests/fixtures/generate_fold_table.py --check   # exit 1 if stale

path_key folds a member name the way some file system compares names: case-insensitively (NTFS, APFS and
HFS+ by default, ext4 with casefold), normalization-insensitively (APFS, HFS+, ext4 casefold), and, as HFS+
did, ignoring default-ignorable code points. Two names with the same key may be written to one path.

The key of a character is NFD(casefold(NFD(c))) with default-ignorable code points removed, then runs of
combining marks sorted by code point (so canonically equivalent strings fold alike). The table holds every
assigned code point whose key differs from str.lower(c), which Rust's char::to_lowercase gives for the rest;
Hangul syllables decompose in code. Data of the Unicode Character Database, from this Python's unicodedata
(the generated file names the version).
"""
import os
import sys
import unicodedata

OUT = os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))), "src", "fold_table.rs")

# DerivedCoreProperties.txt, Default_Ignorable_Code_Point (stable since Unicode 6.3 apart from unassigned additions)
IGNORABLE = [(0x00AD, 0x00AD), (0x034F, 0x034F), (0x061C, 0x061C), (0x115F, 0x1160), (0x17B4, 0x17B5),
             (0x180B, 0x180F), (0x200B, 0x200F), (0x202A, 0x202E), (0x2060, 0x206F), (0x3164, 0x3164),
             (0xFE00, 0xFE0F), (0xFEFF, 0xFEFF), (0xFFA0, 0xFFA0), (0xFFF0, 0xFFF8), (0x1BCA0, 0x1BCA3),
             (0x1D173, 0x1D17A), (0xE0000, 0xE0FFF)]
# NTFS upper-cases names with its own table: there U+0131 (dotless i) and i share I.
EXTRA = {0x0131: "i"}
HANGUL = range(0xAC00, 0xD7A4)


def ignorable(cp):
    return any(lo <= cp <= hi for lo, hi in IGNORABLE)


def sort_marks(s):
    out, run = [], []
    for ch in s:
        if unicodedata.combining(ch):
            run.append(ch)
        else:
            out.extend(sorted(run))
            run = []
            out.append(ch)
    out.extend(sorted(run))
    return "".join(out)


def key(ch):
    if ord(ch) in EXTRA:
        return EXTRA[ord(ch)]
    s = unicodedata.normalize("NFD", unicodedata.normalize("NFD", ch).casefold())
    return sort_marks("".join(c for c in s if not ignorable(ord(c))))


def assigned(cp):
    return not (0xD800 <= cp <= 0xDFFF) and unicodedata.category(chr(cp)) != "Cn"


def tables():
    fold, combining = [], []
    for cp in range(0x110000):
        if not assigned(cp) or ignorable(cp) or cp in HANGUL:
            continue
        ch = chr(cp)
        k = key(ch)
        if k != ch.lower():
            fold.append((cp, k))
        if unicodedata.combining(ch):
            if combining and combining[-1][1] == cp - 1:
                combining[-1][1] = cp
            else:
                combining.append([cp, cp])
    return fold, combining


def rust_str(s):
    return '"' + "".join(c if 0x20 <= ord(c) < 0x7F and c not in '"\\' else "\\u{%x}" % ord(c) for c in s) + '"'


def render():
    fold, combining = tables()
    lines = [
        "// Generated by tests/fixtures/generate_fold_table.py from Python %d.%d's unicodedata — do not edit."
        % sys.version_info[:2],
        "//",
        "// Data of the Unicode Character Database %s, distributed under the Unicode" % unicodedata.unidata_version,
        "// License v3 (rust/LICENSE-UNICODE):",
        "//   Copyright © 1991-2026 Unicode, Inc.",
        "",
        "/// Unicode version of these tables.",
        "#[allow(dead_code)] // read by the tests",
        'pub(crate) const UNICODE_VERSION: &str = "%s";' % unicodedata.unidata_version,
        "",
        "/// Default-ignorable code points (DerivedCoreProperties.txt), which path_key drops.",
        "pub(crate) const IGNORABLE: &[(u32, u32)] = &[",
    ]
    lines += ["    (0x%04X, 0x%04X)," % r for r in IGNORABLE]
    lines += ["];", "", "/// Code points with a nonzero canonical combining class, as ranges.",
              "pub(crate) const COMBINING: &[(u32, u32)] = &["]
    lines += ["    (0x%04X, 0x%04X)," % tuple(r) for r in combining]
    lines += ["];", "",
              "/// Code point -> its folded form, for every code point whose fold differs from its lower case",
              "/// (precomposed letters, case-folding specials); sorted by code point.",
              "pub(crate) const FOLD: &[(u32, &str)] = &["]
    lines += ["    (0x%04X, %s)," % (cp, rust_str(k)) for cp, k in fold]
    lines += ["];", ""]
    return "\n".join(lines)


def main():
    text = render()
    if "--check" in sys.argv:
        with open(OUT, encoding="utf-8") as fh:
            have = fh.read()
        if have != text:
            print("stale: " + OUT)
            return 1
        print("up to date")
        return 0
    with open(OUT, "w", encoding="utf-8") as fh:
        fh.write(text)
    print("wrote", OUT)
    return 0


if __name__ == "__main__":
    sys.exit(main())
